// Golden tax vectors (test/fixtures/tax-golden.json): hand-checkable cases with their arithmetic,
// generated by docs/process/scripts/juice-tax-golden.mjs, an independent re-computation that does
// not import server/juice.js. Sources and verification status: TAX_SOURCES; log:
// docs/process/juice-tax.md.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { taxFor, taxKeys, TAX_SOURCES, TAX_HOUSEHOLD, TAX_COUNTRIES, computeJuice } from '../server/juice.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const GOLDEN = JSON.parse(fs.readFileSync(path.join(ROOT, 'test', 'fixtures', 'tax-golden.json'), 'utf8'));
const DOC = JSON.parse(fs.readFileSync(path.join(ROOT, 'data', 'cities.json'), 'utf8'));
const near = (a, b, tol, msg) => assert.ok(Math.abs(a - b) <= tol, `${msg}: expected ${b} ± ${tol}, got ${a}`);
const jid = (j) => [j.country, j.region, j.local].filter(Boolean).join('-');

test('golden vectors: taxFor matches every hand-computed case', () => {
  assert.ok(GOLDEN.vectors.length >= 300, `${GOLDEN.vectors.length} vectors`);
  for (const v of GOLDEN.vectors) {
    const t = taxFor(v.gross, v.jurisdiction, { household: v.household });
    for (const part of ['income', 'regional', 'social']) near(t[part], v.expected[part], v.tolerance, `${v.id} ${part}`);
    assert.equal(t.household, v.household, v.id);
    assert.ok(v.steps.length > 0, `${v.id}: arithmetic`);
  }
});

test('golden vectors cover every country, US state and local, and Canadian province at three incomes', () => {
  const singles = new Map();
  for (const v of GOLDEN.vectors) {
    if (v.household !== 'single') continue;
    const k = jid(v.jurisdiction);
    singles.set(k, (singles.get(k) || 0) + 1);
  }
  for (const c of TAX_COUNTRIES) assert.ok([...singles.keys()].some((k) => k.split('-')[0] === c), `country ${c}`);
  const states = Object.keys(TAX_SOURCES).filter((k) => /^US-[A-Z]{2}$/.test(k)).map((k) => k.slice(3));
  for (const s of states) assert.ok((singles.get(`US-${s}`) || 0) >= 3, `US state ${s}`);
  const locals = Object.keys(TAX_SOURCES).filter((k) => k.startsWith('US-LOCAL-')).map((k) => k.slice(9));
  for (const l of locals) assert.ok([...singles.entries()].some(([k, n]) => k.endsWith(`-${l}`) && n >= 3), `US local ${l}`);
  for (const p of ['ON', 'BC', 'QC']) assert.ok((singles.get(`CA-${p}`) || 0) >= 3, `province ${p}`);
  // Every jurisdiction a city uses has a vector.
  for (const c of DOC.cities) assert.ok(singles.has(jid(c.tax)), `${c.key}: no golden vector for ${jid(c.tax)}`);
});

test('San Francisco $675K single: the user example, line by line', () => {
  const t = taxFor(675000, { country: 'US', region: 'CA' });
  // Federal: 675,000 - 16,100 = 658,900 on the 2026 single schedule; the SALT cap is $10,000 at
  // this income, so the standard deduction wins.
  near(t.income, 1240 + 4560 + 12166 + 23058 + 17424 + 0.35 * 384375 + 0.37 * 18300, 0.01, 'federal');
  // California: 669,294 on 2025 schedule X; the $153 exemption credit is fully phased out.
  near(t.regional, 110.79 + 303.70 + 607.52 + 965.40 + 1214.56 + 0.093 * 298755 + 0.103 * 74292 + 0.113 * 223523, 0.01, 'California');
  // FICA 11,439 + Medicare 9,787.50 + Additional Medicare 4,275 + CA SDI 8,775.
  near(t.social, 11439 + 9787.5 + 4275 + 8775, 0.01, 'social');
  assert.equal(t.basis, 'single');
});

test('household: basis field per jurisdiction, joint effects only where modeled', () => {
  const sf = { country: 'US', region: 'CA' };
  const s = taxFor(250000, sf);
  const c = taxFor(250000, sf, { household: 'couple' });
  const f = taxFor(250000, sf, { household: 'family' });
  assert.deepEqual([s.basis, c.basis, f.basis], ['single', 'joint', 'joint']);
  assert.ok(c.total < s.total && f.total < c.total, 'MFJ brackets and the child tax credit lower the tax');
  assert.equal(s.note, undefined);
  assert.match(c.note, /married filing jointly/);
  // Individually taxed countries: same tax, basis 'individual' with a note.
  const gb = taxFor(150000, { country: 'GB' }, { household: 'family' });
  assert.equal(gb.basis, 'individual');
  near(gb.total, taxFor(150000, { country: 'GB' }).total, 1e-9, 'UK unchanged');
  // Not modeled: single filer, said so.
  const md = taxFor(200000, { country: 'ES', region: 'MD' }, { household: 'couple' });
  assert.equal(md.basis, 'single');
  assert.match(md.note, /not modeled/);
  const ge = taxFor(200000, { country: 'CH', region: 'GE' }, { household: 'family' });
  assert.equal(ge.basis, 'single', 'Geneva combined schedule is single-only');
  assert.equal(taxFor(200000, { country: 'CH', region: 'ZH' }, { household: 'family' }).basis, 'joint');
  // No-income-tax state: the federal level decides.
  assert.equal(taxFor(200000, { country: 'US', region: 'TX' }, { household: 'couple' }).basis, 'joint');
  assert.equal(taxFor(200000, { country: 'AE' }, { household: 'family' }).basis, 'individual');
  // Unknown household keys fall back to single.
  assert.equal(taxFor(200000, sf, { household: 'nope' }).basis, 'single');
  // computeJuice passes the household through.
  const city = DOC.cities.find((x) => x.key === 'san-francisco-ca-us');
  assert.equal(computeJuice(250000, city, { household: 'family' }).tax, Math.round(f.total));
});

test('TAX_SOURCES: name, https url, as-of, verified flag; TAX_HOUSEHOLD covers every key', () => {
  for (const [k, s] of Object.entries(TAX_SOURCES)) {
    assert.ok(s.name && s.asOf, k);
    assert.match(s.url, /^https:\/\//, k);
    assert.equal(typeof s.verified, 'boolean', k);
    if (s.verified) assert.ok(!s.unverified?.length && !s.estimated, `${k}: verified but lists unverified values`);
    for (const u of s.checkedVia || []) assert.match(u, /^https:\/\//, `${k} checkedVia`);
    assert.ok(TAX_HOUSEHOLD[k], `${k}: no TAX_HOUSEHOLD entry`);
    assert.ok(['joint', 'individual', 'single', 'neutral'].includes(TAX_HOUSEHOLD[k].basis), k);
  }
  for (const c of DOC.cities) for (const k of taxKeys(c.tax)) assert.ok(TAX_SOURCES[k], `${c.key}: ${k}`);
});
